import time

def plan_filter(conn, tenant_id, where_sql, params, T=10_000):
    # bounded count: stops after T+1 matches, so it is cheap even for a broad filter
    # where_sql comes from ac_filter's allow-listed column builder, never from user text
    est = conn.execute(
        f"SELECT count(*) FROM (SELECT 1 FROM attr WHERE tenant_id=%s AND ({where_sql}) LIMIT %s) q",
        [tenant_id, *params, T + 1]).fetchone()[0]
    if est <= T:
        rows = conn.execute(
            f"SELECT uri FROM attr WHERE tenant_id=%s AND ({where_sql})",
            [tenant_id, *params]).fetchall()
        return {"plan": "exact", "est": est, "uris": [r[0] for r in rows]}
    return {"plan": "filtered_ann", "est": est, "uris": None}

def record_plan(conn, tenant_id, plan, est, actual, ms):
    conn.execute("INSERT INTO filter_plan_log(tenant_id,plan,est,actual,ms,at)"
                 " VALUES (%s,%s,%s,%s,%s,now())", (tenant_id, plan, est, actual, ms))

def tune_T(conn, tenant_id, T):
    p95 = conn.execute("SELECT percentile_cont(0.95) WITHIN GROUP (ORDER BY ms) FROM filter_plan_log"
                       " WHERE tenant_id=%s AND plan='exact' AND at > now() - interval '1 day'",
                       (tenant_id,)).fetchone()[0]
    if p95 is not None and p95 < 20:
        return min(T * 2, 200_000)  # exact scans are still cheap: raise the threshold
    return T

