import math
from difflib import SequenceMatcher

# m = P(field agrees | same entity), u = P(field agrees | different entities); tune on labelled pairs
FIELDS = {"email": (0.95, 0.001), "name": (0.90, 0.01), "org_domain": (0.98, 0.20)}
UPPER, LOWER, NAME_SIM = 10.0, 0.0, 0.92

def norm_email(e):
    return e.strip().lower() if e else None

def block_keys(m):
    keys = []
    if m["email"]:
        keys.append(("email", norm_email(m["email"])))
    toks = sorted((m["display_name"] or "").lower().split())
    if toks and m["org_domain"]:
        keys.append(("dom_name", m["org_domain"], "".join(t[:3] for t in toks)))
    return keys

def agree(field, a, b):
    if a is None or b is None:
        return None  # missing is neither agree nor disagree: contributes 0
    if field == "name":
        return SequenceMatcher(None, a.lower(), b.lower()).ratio() >= NAME_SIM
    return a == b

def score_pair(a, b):
    vals = {"email": (norm_email(a["email"]), norm_email(b["email"])),
            "name": (a["display_name"], b["display_name"]),
            "org_domain": (a["org_domain"], b["org_domain"])}
    w, parts = 0.0, {}
    for f, (x, y) in vals.items():
        ag = agree(f, x, y)
        if ag is None:
            continue
        m, u = FIELDS[f]
        parts[f] = math.log2(m / u) if ag else math.log2((1 - m) / (1 - u))
        w += parts[f]
    decision = "merge" if w >= UPPER else "apart" if w < LOWER else "review"
    return decision, w, parts

